class Solution:
    def maximumLength(self, nums, k):
        dp = {}
        for x in nums:
            cur = dp.get(x)
            best = [0] * (k + 1)
            for v, lst in dp.items():
                if v == x: continue
                for j in range(k + 1):
                    if lst[j] > best[j]: best[j] = lst[j]
            nd = list(cur) if cur else [0] * (k + 1)
            for j in range(k + 1):
                b = best[j - 1] if j else 0
                nd[j] = max((cur[j] if cur else 0) + 1, b + 1)
            dp[x] = nd
        return max(max(l) for l in dp.values())

