class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        unordered_map<int, array<int,26>> dp;
        for (int x : nums) {
            auto& cur = dp[x];
            array<int,26> best{};
            for (auto& p : dp) {
                if (p.first == x) continue;
                for (int j = 0; j <= k; j++) best[j] = max(best[j], p.second[j]);
            }
            array<int,26> nd = cur;
            for (int j = 0; j <= k; j++) {
                int b = j ? best[j-1] : 0;
                nd[j] = max(cur[j] + 1, b + 1);
            }
            cur = nd;
        }
        int ans = 0;
        for (auto& p : dp) for (int j = 0; j <= k; j++) ans = max(ans, p.second[j]);
        return ans;
    }
};

