class Solution {
    public int maximumLength(int[] nums, int k) {
        Map<Integer,int[]> dp = new HashMap<>();
        for (int x : nums) {
            int[] cur = dp.computeIfAbsent(x, z -> new int[k+1]);
            int[] best = new int[k+1];
            for (var e : dp.entrySet()) {
                if (e.getKey() == x) continue;
                int[] l = e.getValue();
                for (int j = 0; j <= k; j++) best[j] = Math.max(best[j], l[j]);
            }
            int[] nd = cur.clone();
            for (int j = 0; j <= k; j++) {
                int b = j > 0 ? best[j-1] : 0;
                nd[j] = Math.max(cur[j] + 1, b + 1);
            }
            dp.put(x, nd);
        }
        int ans = 0;
        for (int[] l : dp.values()) for (int j = 0; j <= k; j++) ans = Math.max(ans, l[j]);
        return ans;
    }
}

