var maximumLength = function(nums, k) {
    const dp = new Map();
    for (const x of nums) {
        const cur = dp.get(x) || new Array(k+1).fill(0);
        const best = new Array(k+1).fill(0);
        for (const [v, l] of dp) {
            if (v === x) continue;
            for (let j = 0; j <= k; j++) best[j] = Math.max(best[j], l[j]);
        }
        const nd = cur.slice();
        for (let j = 0; j <= k; j++) {
            const b = j ? best[j-1] : 0;
            nd[j] = Math.max(cur[j] + 1, b + 1);
        }
        dp.set(x, nd);
    }
    let ans = 0;
    for (const l of dp.values()) for (let j = 0; j <= k; j++) ans = Math.max(ans, l[j]);
    return ans;
};
